def solve(n):
    MOD = 998244353

    def compute(failure):
        dp = [0] * (failure + 1)
        cum_sum = [0] * (failure + 1)
        dp_fail_count = defaultdict(int)

        for i in range(1, failure + 1):
            dp[i] = (i % MOD - 1) % MOD
            cum_sum[i] = (cum_sum[i - 1] + dp[i]) % MOD
            dp_fail_count[i] = len([_ for _ in dp if _ == failure])

        res = [0] * (failure + 1)

        for i in range(len(cum_sum)):
            res[-i-1] = cum_sum[fail_to(i, failure) - cum_sum[fail_to(i-1, failure)]]

        return res

    def fail_to(n, failure):
        while n % failure:
            n += 1
        return n

