        swapped = False
        if direction == 0 and row > 1:
            self.tail.append((row, col))
            self.tail = list(set(self.tail))
            self.tail.sort()
            swapped = True
            row -= 1
        if direction == 1 and col > 1:
            self.tail.append((row, col))
            self.tail = list(set(self.tail))
            self.tail.sort()
            swapped = True
            col -= 1
        if direction == 2:
