    if destination not in graph[source]:
        sorted_edges.append([destination, source, 0])
    sorted_edges.sort()

    shortest_edges = []
    visited = set()
    for _, neighbor, weight in sorted_edges:
        if neighbor in visited:
            continue
        visited.add(neighbor)
        shortest_edges.append((weight, neighbor))
