import math
from random import randint

def rand_perm(n, k):
    p = list(range(1, n + 1))
    for _ in range(k):
        l = randint(0, n - 1)
        r = randint(l, n - 1)
        p[l:r+1] = reversed(p[l:r+1])
    return p

def count_inversions(p):
    inversions = 0
    for i in range(len(p)):
        for j in range(i + 1, len(p)):
            if p[i] > p[j]:
                inversions += 1
    return inversions / math.factorial(len(p))

