    mountain = deque(range(n))
    slopes = deque([])
    sliding = True

    while sliding:
        for i in range(n-1):
            if heights[i] + 2 <= heights[i+1]:
                change_heights(i, i+1, mountain, slopes, heights)
                if (i + 1) + 1 <= n:
                    change_heights(i + 1, i + 2, mountain, slopes, heights)

        if not sliding:
            break

        sliding = False

    return heights

def change_heights(start, end, mountain, slopes, heights):
    mountain[start], mountain[end] = mountain[end], mountain[start]
    current_start = mountain.popleft()
    heights[current_start] += 1
    neighbors = mountain
    if start and end < len(mountain):
        for neighbor in list(neighbors).copy():
            current_height_sum = heights.pop()
            new_height = max(heights[neighbor], current_height_sum) + 1
            heights.insert(0, new_height)
            if neighbor in list(slopes):
                slopes.remove(neighbor)

