            return score

        cookies, vertex = heapq.heappop(pq)
        score += cookies
        total_travel_time = -time[pq[0][1]]

        for edge, _, time in edges[vertex]:
            next_travel_time = total_travel_time + time
            if next_travel_time >= T:
                heapq.heappush(pq, (-next_travel_time, edge))
                total_travel_time = next_travel_time

        if pq[0][2] + x[vertex] <= T:
            heapq.heappush(pq, (-T - x[vertex], -T - x[vertex]))
            total_travel_time = T

        while pq[0][2] + x[edges[pq[0][1]][0]] <= T and pq[0][0] < 0:
            heapq.heappop(pq)
            eligible_to_remove = pq[0][0] > 0 and not pq[0][1] in edges[pq[0][1]]
            if eligible_to_remove:
                heapq.heappush(pq, (-x[pq[0][1]], pq[0][1]))
                total_travel_time = -pq[0][0]

