from math import gcd
from functools import lru_cache

def min_cost_gcd(nums):
    @lru_cache(None)
    def dp(i):
        if i == len(nums) - 1:
            return nums[-1]
        return nums[i] + 2 * dp(i + 1)

    result = float('inf')
    for i in range(len(nums) - 1):
        gcd_val = nums[i] % 2
        for j in range(i + 1, len(nums)):
            gcd_val = gcd(gcd_val, nums[j] % 2)
        if gcd_val == 1:
            result = min(result, dp(i + 1) + 2 * dp(j + 1))
    return result

