MOD = 10**9 + 7

def fib_concat(n):
    fibs = [0, 1]

    while len(fibs) < n:
        fibs.append(fibs[-1] + fibs[-2])

    return ''.join(map(str, fibs))

def sum_of_digits(n):
    result = 0
    fib_n_concat = fib_concat(n)

    for i in range(10):
        count = fib_n_concat.count(str(i))
        if count:
            result += (count * i) % MOD

    return result % MOD

