from functools import lru_cache

def count_good_sequences(n, mod):
    @lru_cache(maxsize=None)
    def dp(k, limit, position):
        if k > limit or position >= n:
            return 1
        else:
            return (k * (k - 1) // 2 + sum(dp(k - 1, limit, p + 2) for p in range(position))) % mod

    mod_nums = [None] * 30
    mod_nums[0] = 1
    for i in range(1, 30):
        mod_nums[i] = (1000000000 + mod) * mod_nums[i - 1] % mod

    mod_inv = [None] * 30
    mod_inv[1] = pow(1000000000 + 998244353, -1, 998244353)
    for i in range(2, 30):
        mod_inv[i] = (mod_inv[i - 1] * mod_inv[1]) % mod

    total = 0
    for i in range(1, n + 1):
        total += dp(i, i, 0)

    return total % mod

# Example usage
