def good_sequences(n):
    if n == 1:
        return [1]

    mod = 998244353
    dp = [0] * n
    dp[0] = 1
    dp[1] = 1

    for length in range(2, n):
        for start in range(length):
            if length - start != 1:
                dp[length] += dp[start]
                if dp[start] >= mod:
                    dp[start] -= mod
            dp[length] %= mod

    return dp

